Let ${\mathcal L}$  be a non-local operator with variable order given by
\begin{equation} {\mathcal L} f(x)=\int_{\mathds R^d}\big(f(x+z)-f(x)-\langle\nabla f(x), z\rangle \mathds 1_{\{|z|\leqslant 1\}}\big)
\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz,\quad   f \in C_c^2(\mathds R^d),
\end{equation}
where $\alpha:\mathds R^d \rightarrow (0,2)$
is a measurable function such that
\begin{equation} \begin{split}
& 0<\alpha_1\leqslant \alpha(x) \leqslant \alpha_2<2  \quad \hbox{for }   x \in \mathds R^d,\\
& |\alpha(x)-\alpha(y)|\leqslant c_1(|x-y|^{\beta_1}\wedge 1)   \quad \hbox{for }   x,y\in \mathds R^d,
\end{split}
\end{equation}
for  some constants $c_1\in(0,\infty)$ and $\beta_1\in(0,1]$, and $\kappa:\mathds R^d\times \mathds R^d \rightarrow (0,\infty)$ is a measurable function satisfying
\begin{equation} \begin{split}
& \kappa(x,z)=\kappa(x,-z) \quad \hbox{for }  x,z \in \mathds R^d,\\
&  0<\kappa_1\leqslant \kappa(x,z)\leqslant \kappa_2<\infty \quad \hbox{for }   x,z\in \mathds R^d,\\
&  |\kappa(x,z)-\kappa(y,z)|\leqslant c_2(|x-y|^{\beta_2}\wedge 1)  \quad \hbox{for }   x,y,z\in \mathds R^d,
\end{split}
\end{equation}
for  some constants $c_2\in(0,\infty)$ and $\beta_2 \in (0,1]$.

\begin{split}
& 0<\alpha_1\leqslant \alpha(x) \leqslant \alpha_2<2  \quad \hbox{for }   x \in \mathds R^d,\\
& |\alpha(x)-\alpha(y)|\leqslant c_1(|x-y|^{\beta_1}\wedge 1)   \quad \hbox{for }   x,y\in \mathds R^d,
\end{split}

\begin{split}
& \kappa(x,z)=\kappa(x,-z) \quad \hbox{for }  x,z \in \mathds R^d,\\
&  0<\kappa_1\leqslant \kappa(x,z)\leqslant \kappa_2<\infty \quad \hbox{for }   x,z\in \mathds R^d,\\
&  |\kappa(x,z)-\kappa(y,z)|\leqslant c_2(|x-y|^{\beta_2}\wedge 1)  \quad \hbox{for }   x,y,z\in \mathds R^d,
\end{split}

Suppose that conditions \eqref{e1-3} and \eqref{e1-2}   hold. If $\kappa(x,z)= \kappa (x)$ is
independent of $z$,
then there exists a
  jointly continuous non-negative
function
$p:(0,1]\times \mathds R^d
\times \mathds R^d \rightarrow \mathds R_+:=[0,\infty)$ such that for every $t \in (0,1]$ and $x,y \in \mathds R^d$,
\begin{equation} \frac{\partial p(t,x,y)}{\partial t}={\mathcal L} p(t,\cdot,y)(x),
\end{equation}
and has the following properties.
\begin{enumerate}
\item[(i)]{\bf (Upper bounds)}\,\,
For every $\gamma, c_0>0$, there exist positive constants $c_1 =c_1(\alpha,\kappa,c_0)$ and $c_2 =c_2(\alpha,\kappa,\gamma,c_0)$ such that
for all $t\in(0,1]$ and $x,y\in\mathds R^d$,
\begin{equation} p(t,x,y)\leqslant
\begin{cases}
{c_1}{t^{-{d/\alpha(x)}}},&\quad |x-y|< c_0t^{{1/\alpha(x)}},\\
\frac{c_1t}{|x-y|^{d+\alpha_2}}\wedge \frac{c_2t^{1-\gamma}}{|x-y|^{d+\alpha(x)}},&\quad
c_0t^{{1/\alpha(x)}}\leqslant |x-y|< 1,\\
\frac{c_1t}{|x-y|^{d+\alpha_1}},&\quad|x-y|\geqslant 1.
\end{cases}
\end{equation}
If, in addition,
there are some $x_0\in\mathds R^d$ and $r_0\in(0,\infty]$ such that $\alpha(z)=\alpha(x_0)$ for all $z \in B(x_0,r_0)$,
then there is a positive constant
$c_3 =c_3(\alpha,\kappa,r_0)$ such that for every $t\in (0,1]$ and $y \in \mathds R^d$,
\begin{equation} p(t,x_0,y)\leqslant
\begin{cases}
\frac{c_3 t }{(t^{{1/\alpha(x_0)}}+|y-x_0|)^{d+\alpha(x_0)}},&
|y-x_0|< {r_0}/{2},\\
\frac{c_3 t }{|y-x_0|^{d+\alpha_1}},&|y-x_0|\geqslant {r_0}/{2};
\end{cases}
\end{equation}

\noindent {\bf (Lower bounds)}\,\, There exists a constant $c_4 =c_4(\alpha,\kappa)>0$ such that for all $t\in(0,1]$ and $x,y\in\mathds R^d$,
\begin{equation} p(t,x,y)\geqslant \frac{c_4t}{(t^{1/\alpha(x)}+|x-y|)^{d+\alpha(x)}}.
\end{equation}

\item[(ii)]{\bf (H\"{o}lder regularity and gradient estimates)}\,\,
For any
$\gamma \in (0, \alpha_2]$,
 there exist positive constants
$c_5 =c_5(\alpha,\kappa,\gamma)$ and $R_1=R_1(\alpha,\kappa,\gamma)$ such that for all $t \in (0,1]$ and $x, x', y \in \mathds R^d$ with $|x-x'|\leqslant R_1$,
\begin{equation} \begin{split}
 \big|p(t,x,y)-p(t,x', y)\big|
&\leqslant c_5
|x-x'|^{(\alpha(x)-\gamma)_+\wedge 1}
\big(\rho^{y,0}_{\gamma_0}(t,x-y)+\rho^{y,0}_{\gamma_0}(t,x'-y)\big),
\end{split}
\end{equation}
where $\gamma_0= {\gamma/(2\alpha_2)}$ and
 \begin{equation} \rho_{\gamma}^{y,\beta}(t,x)=t^{\gamma}(|x|^{\beta}\wedge 1)
\begin{cases}
\frac{1}{(t^{{1/\alpha(y)}}+|x|)^{d+\alpha(y)}},&  |x|\leqslant 1,\\
\frac{1}{|x|^{d+\alpha_1}},& |x|> 1.
\end{cases}
\end{equation}
If moreover $\tilde \beta_0(x_0):=\big({\alpha_1\beta_0}/{\alpha(x_0)})\wedge \alpha_1>1-\alpha(x_0)$ for some $x_0 \in \mathds R^d$, then for every fixed $t \in (0,1]$ and $y \in \mathds R^d$,
$p(t,\cdot,y)$ is differentiable at $x=x_0$.
In this case,
for every $\gamma>0$, $t\in(0,1]$ and $ y\in \mathds R^d$,
\begin{equation} |\nabla p(t,\cdot,y)(x_0)|\leqslant c_6 \, \rho^{y,0}_{1-({1/\alpha(x_0)})+
(\beta_0^*/\alpha_2)-(\beta_0^*/\alpha_1)-\gamma}(t,x_0-y)
\end{equation}
  for some $c_6 =c_6(\alpha,\kappa,\gamma,x_0)>0$, where $\beta_0^*:=\beta_0 \wedge\alpha_2$.


\item[(iii)]{\bf (Chapman-Kolmogorov equation)} For every $s,t \in (0,1]$ with $s+t\leqslant 1$,
\begin{equation} \int_{\mathds R^d}p(s,x,z)p(t,z,y)\,dz=p(s+t,x,y),\quad x,y\in \mathds R^d.
\end{equation}

\item[(iv)]{\bf (Conservativeness)} For every $(t,x)\in (0,1]\times \mathds R^d$,
\begin{equation} \int_{\mathds R^d}p(t,x,y)\,dy=1.
\end{equation}

\item[(v)] {\bf (Strong continuity and generator)}
For every $f \in C_{b,u}(\mathds R^d)$, let
$$u_f(t,x):=\int_{\mathds R^d}p(t,x,y)f(y)\,dy.$$
Then
\begin{equation} {\mathcal L} u_f (t, \cdot) (x) \hbox{ exists pointwise}, \quad t \mapsto {\mathcal L} u_f (t, ) (x)
\hbox{  is continuous},
\end{equation}
\begin{equation} \frac{\partial u_f(t,x)}{\partial t}
= {\mathcal L} u_f(t,\cdot)(x),
\quad  t\in (0,1],\ x \in \mathds R^d,
\end{equation}
and
\begin{equation} \lim_{t \downarrow 0}\sup_{x \in \mathds R^d}|u_f(t,x)-f(x)|=0.
\end{equation}

For every $f \in C_{b,u}^2(\mathds R^d):= C_{b,u}(\mathds R^d)\cap C^2(\mathds R^d)$,  we also have
\begin{equation} \frac{\partial u_f(t,x)}{\partial t}=\int_{\mathds R^d}
p(t,x,y){\mathcal L} f(y)\,dy,\quad  t\in
(0,1],\ x \in \mathds R^d
\end{equation} and
\begin{equation} \lim_{t \downarrow 0}\sup_{x \in \mathds R^d}\Big|\frac{1}{t}\cdot\big(
u_f(t,x)-f(x)\big)-{\mathcal L} f(x)\Big|=0.
\end{equation}

\item[(vi)] {\bf (Uniqueness)} Jointly continuous function $p(t, x, y)$ on $(0, 1]\times \mathds R^d\times \mathds R^d$
that is bounded for each $t>0$ and  satisfies
\eqref{t1-1-7} and \eqref{t1-1-2a}-\eqref{t1-1-3} is unique.
\end{enumerate}

p(t,x_0,y)\leqslant
\begin{cases}
\frac{c_3 t }{(t^{{1/\alpha(x_0)}}+|y-x_0|)^{d+\alpha(x_0)}},&
|y-x_0|< {r_0}/{2},\\
\frac{c_3 t }{|y-x_0|^{d+\alpha_1}},&|y-x_0|\geqslant {r_0}/{2};
\end{cases}

\begin{split}
 \big|p(t,x,y)-p(t,x', y)\big|
&\leqslant c_5
|x-x'|^{(\alpha(x)-\gamma)_+\wedge 1}
\big(\rho^{y,0}_{\gamma_0}(t,x-y)+\rho^{y,0}_{\gamma_0}(t,x'-y)\big),
\end{split}

\rho_{\gamma}^{y,\beta}(t,x)=t^{\gamma}(|x|^{\beta}\wedge 1)
\begin{cases}
\frac{1}{(t^{{1/\alpha(y)}}+|x|)^{d+\alpha(y)}},&  |x|\leqslant 1,\\
\frac{1}{|x|^{d+\alpha_1}},& |x|> 1.
\end{cases}

\frac{\partial u_f(t,x)}{\partial t}
= {\mathcal L} u_f(t,\cdot)(x),
\quad  t\in (0,1],\ x \in \mathds R^d,

\frac{\partial u_f(t,x)}{\partial t}=\int_{\mathds R^d}
p(t,x,y){\mathcal L} f(y)\,dy,\quad  t\in
(0,1],\ x \in \mathds R^d

p(t,x_0,y)\leqslant
\begin{cases}
{c_3}{t^{-{d/\alpha (x_0)}}},&\quad |y-x_0|< c_0t^{{1/\alpha(x_0)}}, \smallskip \\
\frac{c_3 t^{2-({\alpha_2}/{\alpha_1})}
}{|y-x_0|^{d+\alpha(x_0)}},& \quad
c_0t^{{1/\alpha(x_0)}}\leqslant |y-x_0|< {r_0}/{2}, \smallskip \\
\frac{c_3 t^{2-({\alpha_2}/{\alpha_1})} }{|x-y_0|^{d+\alpha_1}},&\quad |y-x_0|\geqslant {r_0}/{2}.
\end{cases}

\begin{split}
 \big|p(t,x,y)-p(t,x',y)\big|
&\leqslant c_5|x-x'|^{(\alpha_1-\gamma)_+\wedge 1}
\big(\rho^{y,0}_{\gamma_1}(t,x-y)+ \rho^{y,0}_{\gamma_1}(t,x'-y)\big),
\end{split}

\begin{split}
{\mathcal L} f(x)&=\lim_{\varepsilon \downarrow 0}\frac{1}{2}\int_{\{|z|>\varepsilon\}}
\big(f(x+z)+f(x-z)-2f(x)\big)\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz.
\end{split}

For simplicity, throughout this paper we write ${\mathcal L} f(x)$ as
\begin{equation*}
{\mathcal L} f(x)=\frac{1}{2}\int_{\mathds R^d}
\big(f(x+z)+f(x-z)-2f(x)\big)\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz.
\end{equation*}

For fixed $y \in \mathds R^d$, define
\begin{equation} {\mathcal L}^y f(x):=\int_{\mathds R^d}\big(f(x+z)-f(x)-\langle\nabla f(x), z \rangle\mathds 1_{\{|z|\leqslant 1\}}\big)\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}}\,dz.
\end{equation}

Throughout the paper,  we define for $ f:\mathds R^d\rightarrow \mathds R$,
\begin{equation*}
\delta_f(x;z):=f(x+z)+f(x-z)-2f(x), \quad \ x,z\in \mathds R^d.
\end{equation*}
\begin{equation*}
\delta_{p^y}(t,x;z):=p^y(t,x+z)+p^y(t,x-z)-2p^y(t,x),\quad t\in
(0,\infty),\ x,y,z\in \mathds R^d.
\end{equation*}

\begin{split}
& p(t,x,y)=p^y(t,x-y)+\int_0^t\int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz\,ds,
\end{split}

\begin{split}
|x-z|^{-\alpha(z)}&=|x-z|^{-\alpha(x)}|x-z|^{\alpha(x)-\alpha(z)}\preceq |x-z|^{-\alpha(x)}\cdot \exp\left(\left|\log|x-z|\right|\left|\alpha(x)-\alpha(z)\right|\right)\\
&\preceq |x-z|^{-\alpha(x)}\cdot \exp\left(C\left|\log|x-z|\right|\cdot |x-z|^{\beta_0}\right)
\preceq |x-z|^{-\alpha(x)},
\end{split}

For every $t \in (0,1]$ and $x,y,w\in \mathds R^d$, define
\begin{equation} \begin{split}
I_1(t,x,y,w):=&\int_{\{|z|\leqslant 1\}}\big[\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\wedge 1\big]
\rho^{y,0}_1(t,w
+
z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz,\\
I_2(t,x,y,w):=&\int_{\{|z|>1\}}\rho^{y,0}_1(t,w
+
z)\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\,dz,\\
I_3(t,x,y):=&\int_{\mathds R^d}\big[\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\wedge 1\big]  \left(
\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}
+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\right)\,dz.
\end{split}
\end{equation}
Then there exists a constant $c_1:=c_1(\alpha,\kappa)$ such that for every
$x,y,w \in \mathds R^d$ and $t \in (0,1]$,
\begin{equation} \begin{split}
 I_1(t,x,y,w) \leqslant
\begin{cases}
c_1(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),\ & |w|\leqslant {1}/{2},\\
c_1\big[1+|\log|w||+(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\big]\rho^{y,0}_0(t,w),\ &
|w|> {1}/{2};
\end{cases}\end{split}
\end{equation}
\begin{equation} I_2(t,x,y,w)\leqslant
\begin{cases}
c_1\rho^{y,0}_1(t,w),\ & |w|\leqslant {1}/{2},\\
c_1\big(1+|\log|w||\big)\rho^{y,0}_0(t,w),\ & |w|>{1}/{2};
\end{cases}
\end{equation} and
\begin{equation} I_3(t,x,y)\leqslant
c_1(1+|\log t|)t^{-({\overline{\alpha}(y;x)}/{\alpha(y)})}.
\end{equation}

\begin{split}
 I_1(t,x,y,w) \leqslant
\begin{cases}
c_1(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),\ & |w|\leqslant {1}/{2},\\
c_1\big[1+|\log|w||+(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\big]\rho^{y,0}_0(t,w),\ &
|w|> {1}/{2};
\end{cases}\end{split}

I_2(t,x,y,w)\leqslant
\begin{cases}
c_1\rho^{y,0}_1(t,w),\ & |w|\leqslant {1}/{2},\\
c_1\big(1+|\log|w||\big)\rho^{y,0}_0(t,w),\ & |w|>{1}/{2};
\end{cases}

We only prove \eqref{l1-1-1} and \eqref{l1-1-2}, since
the proof of \eqref{l1-1-3} is similar and more direct. We denote $I_1(t,x,y,w)$ and $I_2(t,x,y,w)$ by $I_1$ and $I_2$, respectively.
Write
\begin{align*}
I_1&=\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}
\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz  +\int_{\{t^{{1/\alpha(y)}}<|z|\leqslant 1\}}\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&=:I_{11}+I_{12}.
\end{align*}
We will divide the proof into the following three subcases.



{\bf Case (a): $0\leqslant |w| \leqslant 2t^{{1/\alpha(y)}}$.}



Since, by \eqref{e3-0}, \begin{equation} \rho^{y,0}_1(t,w{+} z)\preceq t^{-{d/\alpha(y)}}\quad \textrm{ for all } t\in(0,1]\textrm{ and }  y,z,w\in\mathds R^d,\end{equation} we have
\begin{align*}
I_{11}&\preceq t^{-{(d+2)}/{\alpha(y)}}\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}
\frac{(1+|\log|z|)|z|^2}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&\preceq(1+|\log t|)t^{-{(d+\overline\alpha(y;x))}/{\alpha(y)}} \preceq(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where in the last inequality we have used the fact that \begin{equation} t^{-{d/\alpha(y)}}\preceq \rho^{y,0}_1(t,w)
\quad \textrm{ when } |w|\leqslant 2t^{{1/\alpha(y)}}.\end{equation}

Applying \eqref{e:ond} and \eqref{e:one1} to
$I_{12}$ and $I_2$ again, we get
\begin{align*}
I_{12}&\preceq t^{-{d/\alpha(y)}}\int_{\{t^{{1/\alpha(y)}}<|z|\leqslant 1\}}
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz \preceq(1+|\log t|)t^{-({d+\overline\alpha(y;x)})/{\alpha(y)}}\\
& \preceq(1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w)
\end{align*} and
\begin{align*}
I_2&\preceq  t^{-{d/\alpha(y)}}\int_{\{|z|> 1\}} \frac{1+\log
|z|}{|z|^{d+\alpha_1}}\,dz\preceq \rho^{y,0}_1(t,w).
\end{align*}


{\bf Case (b): $2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2}$.}

When $|w|>2t^{{1/\alpha(y)}}$ and $|z|\leqslant t^{{1/\alpha(y)}}$,
$
|w{+} z|\geqslant |w|-{|w|}/{2}\geqslant {|w|}/{2},
$
which along with \eqref{e3-0} implies that
\begin{equation} \begin{split}
\rho^{y,0}_0(t,w{+} z)&\preceq
\frac{1}{(t^{{1/\alpha(y)}}+|w{+} z|)^{d+\alpha(y)}}\preceq \frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}.
\end{split}
\end{equation}
Therefore,
\begin{align*}
I_{11}&\preceq \frac{t^{1-{2}/{\alpha(y)}}}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}
\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}\frac{(1+|\log |z||)|z|^2}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
& \preceq (1+|\log t|)t^{1-({\overline\alpha(y;x)}/{\alpha(y)})}\frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq (1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where the last step is due to the fact that \begin{equation} \frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq \rho^{y,0}_0(t,w)\quad
\textrm{ when }|w|>2t^{{1/\alpha(y)}}.\end{equation}

On the other hand, we have the following decomposition for $I_{12}$:
\begin{align*}
I_{12}&=\int_{\{
t^{{1/\alpha(y)}}<|z|\leqslant{|w|}/{2}\}}\rho^{y,0}_1(t,w{+} z)
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz  + \int_{\{{|w|}/{2}\leqslant |z|\leqslant 1\}}\rho^{y,0}_1(t,w{+} z)
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&=:I_{121}+I_{122}.
\end{align*}
If $|z|\leqslant {|w|}/{2}$, then $|w{+} z|\geqslant {|w|}/{2}$,
and so \eqref{l2-1-7} still holds. Hence, we have
\begin{align*}
I_{121}&\preceq \frac{t}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}
\int_{\{|z|>t^{{1/\alpha(y)}}\}}\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&\preceq (1+|\log t|)t^{-{\overline
\alpha(y;x)}/{\alpha(y)}}\frac{t}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq (1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*} where the last step follows from \eqref{e:one-2}.
Meanwhile,
\begin{align*}
I_{122}&\preceq \frac{1+|\log|w||}{|w|^{d+\overline{\alpha}(y;x)}}\int_{\mathds R^d}\rho^{y,0}_1(t,w{+} z)\,dz\preceq \frac{1+|\log|w||}{|w|^{d+\overline{\alpha}(y;x)}}\\
&\preceq \frac{(1+|\log|w||)|w|^{\alpha(y)-\overline{\alpha}(y;x)}}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where the second inequality is due to \eqref{l3-1-1-00},
in the third inequality we have used the fact that $$|w|^{-d-\alpha(y)}\preceq
(t^{{1/\alpha(y)}}+|w|)^{-d-\alpha(y)}\quad \textrm{ when } 2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2},$$ and the fourth
inequality follows from
$$ (1+|\log|w||)|w|^{\alpha(y)-\overline{\alpha}(y;x)}\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}
\quad\textrm{ when }2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2}.$$
Combining with all the estimates above, we obtain
$$I_1\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w).$$

Furthermore, note that if $|w|\leqslant {1}/{2}$ and $|z|>1$, then
$
|w{+} z|\geqslant |z|-|w|\geqslant 2|w|-|w|=|w|.
$
Therefore, for every $y,z,w\in\mathds R^d$ and $t\in(0,1]$ with $|z|>1$ and $2t^{{1/\alpha(y)}}\leqslant |w|\leqslant{1}/{2}$,
\begin{align*}
\rho^{y,0}_0(t,w{+} z)& \preceq
\begin{cases}
|w|^{-d-\alpha(y)}, \ &\ |w{+} z|\leqslant 1,\\
|w|^{-d-\alpha_1},\ &\  |w{+} z|> 1
\end{cases}\\
&\preceq |w|^{-d-\alpha(y)},
\end{align*}
which implies that
\begin{align*}
I_2&\preceq \frac{t}{|w|^{d+\alpha(y)}}
\int_{\{|z|\geqslant 1\}} \frac{1+\log |z|}{|z|^{d+\alpha_1}}\,dz\preceq
\frac{t}{|w|^{d+\alpha(y)}}\preceq \rho^{y,0}_1(t,w).
\end{align*}

{\bf{Case (c): $|w|>{1}/{2}$}.}

By adjusting the constants properly, it is easy to verify that
\begin{align*}
I_1+I_2&\preceq \int_{\{|z|\leqslant {1}/{4}\}}\big[\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\wedge 1\big]
\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz +\int_{\{|z|>{1}/{4}\}}\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\,dz\\
&=:J_1+J_2.
\end{align*}
Note that when $|w|>{1}/{2}$ and $|z|\leqslant {1}/{4}$,
$|w{+} z|\geqslant |w|-|z|\geqslant {|w|}/{2}>{1}/{4}$, which implies
that
$$\rho^{y,0}_1(t,w{+} z)\preceq \frac{t}{|w|^{d+\alpha_1}}.$$ On the other hand,
\begin{align*}
&\int_{{\{|z|\leqslant 1\}}}\big[\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\wedge 1\big]
\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
